import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useLocation, useNavigate } from 'react-router-dom';
import SearchBar from '../components/SearchBar';
const style= `
.search-bar {
  display: flex;
  gap: 10px;
  justify-content: center;
  margin: 1rem;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
  padding: 1rem;
}

.card {
  background: #fff;
  border-radius: 10px;
  padding: 1rem;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
  cursor: pointer;
  transition: transform 0.2s ease;
}

.card:hover {
  transform: translateY(-4px);
}

.card .flag {
  font-size: 2rem;
  margin-bottom: 0.5rem;
  text-align: center;
}
`

export default function SearchResults() {
  const [countries, setCountries] = useState([]);
  const [sortBy, setSortBy] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const location = useLocation();
  const navigate = useNavigate();

  const fetchCountries = async () => {
    setLoading(true);
    setError(null);
    try {
      const query = new URLSearchParams(location.search);
      if (sortBy) query.set('sortBy', sortBy);
      const { data } = await axios.get(`http://localhost:5000/api/countries/search?${query.toString()}`);
      setCountries(data.results);
    } catch (err) {
      setError('Failed to fetch countries.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCountries();
  }, [location.search, sortBy]);

  return (
    <div className="search-results">
      <SearchBar
        onSearch={({ name, continent }) => {
          const params = new URLSearchParams();
          if (name) params.set('name', name);
          if (continent) params.set('continent', continent);
          navigate(`/search?${params.toString()}`);
        }}
        compact={true}
      />

      <select onChange={e => setSortBy(e.target.value)}>
        <option value="">Sort By</option>
        <option value="name">Name</option>
        <option value="capital">Capital</option>
        <option value="currency">Currency</option>
      </select>

      {loading && <p>Loading...</p>}
      {error && <p>{error}</p>}

      <div className="card-grid">
        {countries.map(c => (
          <div key={c.cca2} className="card" onClick={() => navigate(`/country/${c.cca2}`)}>
            <div className="flag">{c.flag}</div>
            <h3>{c.name}</h3>
            <p><strong>Capital:</strong> {c.capital}</p>
            <p><strong>Currency:</strong> {c.currencies.join(', ')}</p>
          </div>
        ))}
      </div>
    </div>
  );
}
